from fractions import Fraction as F
import json
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
tests='TUVW'
cost=dict(zip(tests,map(F,['1.8','1.5','1.2','0.8'])))
loss={'A':[0,11,6,16],'B':[22,0,20,8],'C':[16,23,0,7],'D':[18,11,20,0]}
def repair(ids):
    z=sum(rows[i][1] for i in ids)
    return min((F(sum(rows[i][1]*ls['ABCD'.index(rows[i][0])] for i in ids),z),a) for a,ls in loss.items())
def policy(ids,available,budget):
    options={'STOP':repair(ids)[0]}
    z=sum(rows[i][1] for i in ids)
    if budget:
        for t in available:
            v=cost[t]
            for b in (0,1):
                sub=[i for i in ids if rows[i][2][tests.index(t)]==b]
                if sub:
                    v+=F(sum(rows[i][1] for i in sub),z)*policy(sub,[s for s in available if s!=t],budget-1)[0]
            options[t]=v
    key=min(options,key=options.get)
    return options[key],repair(ids)[1] if key=='STOP' else key,options
ids=list(range(8))
v,first,opts=policy(ids,list(tests),2)
nxt={}
if first in tests:
    for b in (0,1):
        sub=[i for i in ids if rows[i][2][tests.index(first)]==b]
        nxt[str(b)]=policy(sub,[s for s in tests if s!=first],1)[1] if sub else 'IMPOSSIBLE'
print(json.dumps({'first':first,'first_losses':{k:float(v) for k,v in opts.items()},'next':nxt}))
print('Exact first losses:',{k:str(v) for k,v in opts.items()})
print('Weight sum:',sum(r[1] for r in rows))
# Independently check V branch decisions by direct one-test terminal partitions.
for b in (0,1):
    sub=[i for i in ids if rows[i][2][2]==b]
    print('V outcome',b,'stop',repair(sub),'remaining options',policy(sub,['T','U','W'],1)[2])

