from fractions import Fraction as F
import json
# One observation of W=1: the repeated display is the same evidence.
rows=[('A',3,{'T':0,'U':0,'V':0}),('B',5,{'T':0,'U':0,'V':1}),('D',5,{'T':0,'U':0,'V':1})]
L={'A':[0,11,6,16],'B':[22,0,20,8],'C':[16,23,0,7],'D':[18,11,20,0]}
cost={'T':F('1.8'),'U':F('1.5'),'V':F('7.2')}
def solve(rows):
    z=sum(w for m,w,r in rows)
    return {a:F(sum(w*ls['ABCD'.index(m)] for m,w,r in rows),z) for a,ls in L.items()}
def answer():
    z=sum(w for m,w,r in rows)
    posterior={m:float(F(sum(w for n,w,r in rows if n==m),z)) for m in 'ABCD'}
    losses=solve(rows)
    branches={}
    for t,c in cost.items():
        val=c
        branches[t]={}
        for b in (0,1):
            sub=[row for row in rows if row[2][t]==b]
            if not sub:
                branches[t][str(b)]='IMPOSSIBLE'
                continue
            ls=solve(sub)
            a=min(ls,key=ls.get)
            branches[t][str(b)]=a
            val+=F(sum(w for m,w,r in sub),z)*ls[a]
        losses[t]=val
    action=min(losses,key=losses.get)
    return {'posterior':posterior,'remaining_losses':{a:float(v) for a,v in losses.items()},'action':action,'repair_after':branches.get(action,{})}
a=answer()
# Independent expected values: total weight 13; repair numerators 135,106,83,109.
expected={'A':F(135,13),'B':F(106,13),'C':F(83,13),'D':F(109,13),'T':F(83,13)+F('1.8'),'U':F(83,13)+F('1.5'),'V':F(40,13)+F('7.2')}
assert all(abs(a['remaining_losses'][k]-float(v))<1e-12 for k,v in expected.items())
assert a['action']=='C' and a['repair_after']=={}
print(json.dumps(a))

